<?php
/** Home 09 Services — sliced from static-mirror/index.html. @package ErfanSanat\Theme */
declare(strict_types=1);
if (!defined('ABSPATH')) exit;
$esSection = is_array($GLOBALS['es_section'] ?? null) ? $GLOBALS['es_section'] : [];
$esF = is_array($esSection['fields'] ?? null) ? $esSection['fields'] : [];
$esField = static fn(string $k, string $d = ''): string => isset($esF[$k]) && is_scalar($esF[$k]) ? (string) $esF[$k] : $d;

$esServices = [['نورپردازی میدان', 'طراحی و اجرای نورپردازی میادین شهری', 'light-sphere.jpg'], ['نورپردازی خیابان', 'روشنایی معابر و بلوارها', 'string-lights.jpg'], ['نورپردازی پل', 'نورپردازی سازه‌ای پل‌ها', 'light-tunnel.jpg'], ['المان نوری', 'المان‌های تعاملی و مناسبتی', 'light-element.jpg'], ['نورپردازی نما', 'نمای ساختمان‌های شاخص', 'sun-light.jpg']];
if (isset($esF['items']) && is_array($esF['items'])) $esServices = array_map(static fn($s): array => [(string)($s['title'] ?? ''), (string)($s['desc'] ?? ''), (string)($s['image'] ?? 'hero.jpg')], array_values($esF['items']));
?>
<section id="services" class="mx-auto max-w-[1300px] px-5 pt-20 lg:px-8" data-services-section="true"><h2 class="text-2xl font-black text-slate-900 sm:text-3xl"><?php echo esc_html($esField('title', 'خدمات تخصصی نورپردازی شهری')); ?></h2>
<div class="mt-8 grid gap-6 lg:grid-cols-2"><div class="space-y-2">
<?php foreach ($esServices as $i => [$t, $d, $img]) : ?><div data-service-row class="cursor-pointer rounded-2xl border p-4 <?php echo $i === 0 ? 'border-emerald-200 bg-emerald-50/60' : 'border-slate-200/80 bg-white'; ?>"><div class="flex items-center gap-3"><span data-service-num class="text-xs font-black text-emerald-700"><?php echo esc_html(str_pad((string) ($i + 1), 2, '0', STR_PAD_LEFT)); ?></span><span data-service-indicator class="h-8 w-1 rounded-full bg-emerald-600"></span><h3 data-service-heading class="text-sm font-black text-slate-900"><?php echo esc_html($t); ?></h3><span data-service-row-icon class="mr-auto text-emerald-700">←</span></div><div data-service-desc class="<?php echo $i === 0 ? '' : 'hidden'; ?>"><p data-service-desc-text class="pt-3 text-xs leading-6 text-slate-600"><?php echo esc_html($d); ?></p><img data-service-mobile-img src="<?php echo esc_url(es_image_uri($img)); ?>" alt="" class="mt-3 aspect-video w-full rounded-xl object-cover lg:hidden" loading="lazy" decoding="async" /><span data-service-title class="hidden"><?php echo esc_html($t); ?></span><img data-service-img src="<?php echo esc_url(es_image_uri($img)); ?>" alt="" class="hidden" loading="lazy" decoding="async" /><span data-service-counter class="hidden"><?php echo esc_html((string) ($i + 1)); ?></span></div></div><?php endforeach; ?>
</div><div class="relative hidden overflow-hidden rounded-[2rem] lg:block"><img data-service-preview-img="true" src="<?php echo esc_url(es_image_uri($esServices[0][2])); ?>" alt="" class="h-full min-h-[380px] w-full object-cover" loading="lazy" decoding="async" /><div class="absolute bottom-0 right-0 left-0 bg-gradient-to-t from-slate-950/80 to-transparent p-6 text-white"><span data-service-preview-counter="true" class="text-xs font-bold">۰۱</span><h3 data-service-preview-title="true" class="mt-1 text-lg font-black"><?php echo esc_html($esServices[0][0]); ?></h3><p data-service-preview-desc="true" class="text-xs leading-6 text-slate-200"><?php echo esc_html($esServices[0][1]); ?></p><span data-service-preview-icon class="hidden"></span></div></div></div></section>
